/* ============================================================
   Teacher page logic
   ============================================================ */
let PROFILE = null;
let YEARS = [];
let SELECTED_YEAR_ID = null;
let CLASS = null;
let STUDENTS = [];
let MONEYBOXES = [];
let SEARCH_TERM = '';

requireRole('teacher', async (user, profile)=>{
  PROFILE = profile;
  document.getElementById('whoami').innerHTML = `Signed in as <b>${esc(profile.displayName || profile.email)}</b>`;

  await loadYears();
  document.getElementById('yearSelect').addEventListener('change', async (e)=>{
    SELECTED_YEAR_ID = e.target.value;
    await loadForSelectedYear();
  });
  document.getElementById('searchBox').addEventListener('input', (e)=>{
    SEARCH_TERM = e.target.value.trim().toLowerCase();
    renderStudentList();
  });
  document.getElementById('xlsxInput').addEventListener('change', handleXlsxUpload);
  document.getElementById('addStudentBtn').addEventListener('click', addStudentManually);
  document.getElementById('newStudentName').addEventListener('keydown', (e)=>{
    if(e.key === 'Enter') addStudentManually();
  });

  await loadMoneyboxes();
  await loadForSelectedYear();
});

async function loadYears(){
  const snap = await db.collection('years').orderBy('createdAt').get();
  YEARS = snap.docs.map(d=>({id:d.id, ...d.data()}));
  const active = YEARS.find(y=>y.isActive);
  SELECTED_YEAR_ID = active ? active.id : (YEARS[0] ? YEARS[0].id : null);
  const sel = document.getElementById('yearSelect');
  sel.innerHTML = YEARS.length
    ? YEARS.map(y=>`<option value="${y.id}" ${y.id===SELECTED_YEAR_ID?'selected':''}>${esc(y.label)}${y.isActive?' (active)':''}</option>`).join('')
    : '<option value="">No years yet</option>';
}

async function loadMoneyboxes(){
  try{
    const doc = await db.collection('config').doc('moneyboxes').get();
    if(doc.exists && Array.isArray(doc.data().boxes)) MONEYBOXES = doc.data().boxes;
    else if(doc.exists && Array.isArray(doc.data().labels)) MONEYBOXES = doc.data().labels.map(l=>({id:l, label:l}));
  }catch(e){ /* defaults stay empty */ }
}

async function loadForSelectedYear(){
  const classId = (PROFILE.assignments && SELECTED_YEAR_ID) ? PROFILE.assignments[SELECTED_YEAR_ID] : null;

  if(!SELECTED_YEAR_ID || !classId){
    CLASS = null; STUDENTS = [];
    document.getElementById('className').textContent = '';
    document.getElementById('pageTitle').textContent = SELECTED_YEAR_ID ? 'No class assigned' : 'No years set up yet';
    document.getElementById('statsRow').innerHTML = '';
    document.getElementById('studentList').innerHTML = `<div class="empty-note">${SELECTED_YEAR_ID ? "You don't have a class assigned for this year yet. Ask your admin to assign one." : 'Ask your admin to create a year first.'}</div>`;
    document.querySelector('.card-head').style.display = 'none';
    return;
  }

  document.querySelector('.card-head').style.display = 'flex';
  const doc = await db.collection('years').doc(SELECTED_YEAR_ID).collection('classes').doc(classId).get();
  if(!doc.exists){
    toast('Your assigned class could not be found for this year.');
    CLASS = null; STUDENTS = [];
    document.getElementById('studentList').innerHTML = `<div class="empty-note">Class not found.</div>`;
    return;
  }
  CLASS = { id: doc.id, ...doc.data() };
  document.getElementById('className').textContent = '· ' + CLASS.name;
  document.getElementById('pageTitle').textContent = CLASS.name;
  await loadStudents();
  render();
}

async function loadStudents(){
  const snap = await db.collection('years').doc(SELECTED_YEAR_ID).collection('classes').doc(CLASS.id).collection('students').orderBy('name').get();
  STUDENTS = snap.docs.map(d=>({id:d.id, ...d.data()}));
}

async function addStudentManually(){
  if(!CLASS){ toast('No class assigned yet.'); return; }
  const input = document.getElementById('newStudentName');
  const name = input.value.trim();
  if(!name){ toast('Enter a student name first.'); return; }
  if(STUDENTS.some(s=>s.name.trim().toLowerCase() === name.toLowerCase())){
    toast('That name is already on the list.');
    return;
  }
  const btn = document.getElementById('addStudentBtn');
  btn.disabled = true;
  try{
    const ref = await studentsCollection().add({ name, paid:false, paidDate:null, amount:null });
    STUDENTS.push({ id: ref.id, name, paid:false, paidDate:null, amount:null });
    STUDENTS.sort((a,b)=>a.name.localeCompare(b.name));
    input.value = '';
    render();
    toast('Student added.');
  }catch(e){ console.error(e); toast('Could not add that student — please retry.'); }
  btn.disabled = false;
}

function render(){
  renderStats();
  renderStudentList();
}

function renderStats(){
  const paid = STUDENTS.filter(s=>s.paid);
  const collected = paid.reduce((sum,s)=>sum + (Number(s.amount)||CLASS.fee), 0);
  const expected = STUDENTS.length * CLASS.fee;
  document.getElementById('statsRow').innerHTML = `
    <div class="stat"><div class="num">${paid.length}/${STUDENTS.length}</div><div class="lbl">Students paid</div></div>
    <div class="stat"><div class="num">${fmtMoney(collected)}</div><div class="lbl">Collected so far</div></div>
    <div class="stat"><div class="num">${fmtMoney(expected)}</div><div class="lbl">Total expected</div></div>
  `;
}

function renderStudentList(){
  const list = document.getElementById('studentList');
  const filtered = SEARCH_TERM ? STUDENTS.filter(s=>s.name.toLowerCase().includes(SEARCH_TERM)) : STUDENTS;

  if(!STUDENTS.length){
    list.innerHTML = `<div class="empty-note">No students yet. Upload an Excel file with one name per row to get started.</div>`;
    return;
  }
  if(!filtered.length){
    list.innerHTML = `<div class="empty-note">No students match "${esc(SEARCH_TERM)}".</div>`;
    return;
  }

  list.innerHTML = filtered.map(s=>{
    const boxes = MONEYBOXES.map(b=>{
      const alloc = (CLASS.boxAllocations && CLASS.boxAllocations[b.id]) || 0;
      return `<span class="box-chip ${s.paid?'on':''}">${esc(b.label)}${alloc ? ' · ' + fmtMoney(alloc) : ''}</span>`;
    }).join('');
    return `
      <div class="student-row" data-id="${s.id}">
        <div>
          <div class="student-name">${esc(s.name)}</div>
          ${s.paid ? `<div class="student-date">Paid ${esc(s.paidDate||'')} · ${fmtMoney(s.amount||CLASS.fee)}</div>` : ''}
        </div>
        <div class="boxes">${boxes}</div>
        <div class="row-actions">
          <button class="pill-btn ${s.paid?'paid':'unpaid'}" data-action="toggle">${s.paid?'✓ Paid':'Mark paid'}</button>
          <button class="btn-icon" data-action="receipt" title="Print receipt">🖨</button>
          <button class="btn-icon" data-action="delete" title="Remove student">✕</button>
        </div>
      </div>
    `;
  }).join('');

  list.querySelectorAll('.student-row').forEach(row=>{
    const id = row.dataset.id;
    const student = STUDENTS.find(s=>s.id===id);
    row.querySelector('[data-action="toggle"]').onclick = ()=> togglePaid(student);
    row.querySelector('[data-action="receipt"]').onclick = ()=> openReceipt(student);
    row.querySelector('[data-action="delete"]').onclick = ()=> deleteStudent(student);
  });
}

function studentsCollection(){
  return db.collection('years').doc(SELECTED_YEAR_ID).collection('classes').doc(CLASS.id).collection('students');
}

async function togglePaid(student){
  student.paid = !student.paid;
  student.paidDate = student.paid ? todayStr() : null;
  student.amount = student.paid ? CLASS.fee : null;
  render();
  try{
    await studentsCollection().doc(student.id).update({ paid: student.paid, paidDate: student.paidDate, amount: student.amount });
  }catch(e){ console.error(e); toast('Could not save that change — please retry.'); }
}

async function deleteStudent(student){
  if(!confirm(`Remove ${student.name} from the class list?`)) return;
  STUDENTS = STUDENTS.filter(s=>s.id!==student.id);
  render();
  try{ await studentsCollection().doc(student.id).delete(); }
  catch(e){ console.error(e); toast('Could not delete that student — please retry.'); }
}

/* ================= OFFICIAL RECEIPT (PIBG template) ================= */
const SCHOOL_NAME_LINE1 = 'PERSATUAN IBU BAPA DAN GURU';
const SCHOOL_NAME_LINE2 = 'SEKOLAH MENENGAH KEBANGSAAN TELUK BAYU';
/* Logos embedded as base64 so the receipt always prints correctly with no extra image files to manage. */
const PIBG_LOGO_SRC = 'data:image/png;base64,';
const SCHOOL_BADGE_SRC = 'data:image/png;base64,';

function openReceipt(student){
  if(!student.paid){ toast('Mark this student as paid before printing a receipt.'); return; }
  openReceiptEditor(student);
}

async function openReceiptEditor(student){
  const baseAmount = Number(student.amount) || CLASS.fee || 0;
  let items = student.receiptItems && student.receiptItems.length
    ? student.receiptItems.map(it=>({...it}))
    : [{ label: 'Sumbangan PIBG ( Hanya seorang murid bagi 1 keluarga )', amount: baseAmount, locked: true }];

  function renderItemRows(){
    return items.map((it,i)=>`
      <div class="row" data-idx="${i}" style="align-items:flex-end; margin-bottom:6px;">
        <div class="field" style="margin-bottom:0;">
          <label>${i===0?'Bil 1 (auto)':'Description'}</label>
          <input type="text" class="riLabel" data-idx="${i}" value="${esc(it.label)}" ${it.locked?'disabled':''}>
        </div>
        <div class="field" style="max-width:120px; margin-bottom:0;">
          <label>RM</label>
          <input type="number" class="riAmount" data-idx="${i}" value="${it.amount}" min="0" step="0.01" ${it.locked?'disabled':''}>
        </div>
        ${!it.locked ? `<button class="btn-icon" data-action="removeItem" data-idx="${i}" title="Remove row">✕</button>` : `<span style="width:26px;"></span>`}
      </div>
    `).join('');
  }

  openModal(`
    <span class="modal-close" onclick="closeModal()">✕</span>
    <h3>Receipt for ${esc(student.name)}</h3>
    <p class="tiny muted" style="margin-top:6px;">Row 1 fills in automatically from the class fee. Add more rows for anything else this payment covers.</p>
    <div id="receiptItemsWrap" style="margin-top:14px;">${renderItemRows()}</div>
    <button class="btn btn-sm" id="addItemRowBtn" style="margin-top:6px;">+ Add row</button>
    <div class="tiny" id="receiptTotalLine" style="margin:14px 0;"></div>
    <button class="btn btn-primary btn-block" id="printReceiptBtn">Print receipt</button>
  `);

  function refresh(){
    document.getElementById('receiptItemsWrap').innerHTML = renderItemRows();
    bindRowEvents();
    const total = items.reduce((s,it)=>s+(Number(it.amount)||0),0);
    document.getElementById('receiptTotalLine').innerHTML = `Total: <b class="mono">${fmtMoney(total)}</b>`;
  }

  function bindRowEvents(){
    document.querySelectorAll('.riLabel').forEach(inp=>{
      inp.addEventListener('input', ()=>{ items[+inp.dataset.idx].label = inp.value; });
    });
    document.querySelectorAll('.riAmount').forEach(inp=>{
      inp.addEventListener('input', ()=>{
        items[+inp.dataset.idx].amount = parseFloat(inp.value)||0;
        document.getElementById('receiptTotalLine').innerHTML = `Total: <b class="mono">${fmtMoney(items.reduce((s,it)=>s+(Number(it.amount)||0),0))}</b>`;
      });
    });
    document.querySelectorAll('[data-action="removeItem"]').forEach(btn=>{
      btn.onclick = ()=>{ items.splice(+btn.dataset.idx,1); refresh(); };
    });
  }

  document.getElementById('addItemRowBtn').onclick = ()=>{
    items.push({ label:'', amount:0, locked:false });
    refresh();
  };

  refresh();

  document.getElementById('printReceiptBtn').onclick = async ()=>{
    const cleanItems = items.map(it=>({ label: (it.label||'').trim(), amount: Number(it.amount)||0, locked: !!it.locked })).filter(it=>it.label);
    if(!cleanItems.length){ toast('Add at least one item to the receipt.'); return; }
    try{
      const receiptNo = await ensureReceiptNo(student);
      await studentsCollection().doc(student.id).update({ receiptItems: cleanItems });
      student.receiptItems = cleanItems;
      closeModal();
      printOfficialReceipt(student, cleanItems, receiptNo);
    }catch(e){ console.error(e); toast('Could not prepare the receipt — please retry.'); }
  };
}

/* Local, self-contained modal helpers so this page doesn't depend on shared modal
   code elsewhere behaving the same way — teacher.html's #modalBackdrop is only used here. */
function openModal(html){
  document.getElementById('modalBody').innerHTML = html;
  document.getElementById('modalBackdrop').style.display = 'flex';
}
function closeModal(){
  document.getElementById('modalBackdrop').style.display = 'none';
  document.getElementById('modalBody').innerHTML = '';
}

/* Generates a unique receipt number formatted as {year}{6-digit suffix}, e.g. 2026402317.
   Built from the current timestamp + a random pad rather than a shared counter document,
   so it only ever writes to the student's own record — no elevated Firestore permissions
   needed. Generated once per student and reused on reprints. */
async function ensureReceiptNo(student){
  if(student.receiptNo) return student.receiptNo;
  const yearLabel = (YEARS.find(y=>y.id===SELECTED_YEAR_ID)||{}).label || '';
  const yearMatch = yearLabel.match(/\d{4}/);
  const yearNum = yearMatch ? yearMatch[0] : String(new Date().getFullYear());
  const tsPart = String(Date.now()).slice(-4);
  const randPart = String(Math.floor(Math.random()*100)).padStart(2,'0');
  const receiptNo = yearNum + tsPart + randPart;
  student.receiptNo = receiptNo;
  await studentsCollection().doc(student.id).update({ receiptNo });
  return receiptNo;
}

function printOfficialReceipt(student, items, receiptNo){
  const total = items.reduce((s,it)=>s+(Number(it.amount)||0),0);
  const rows = items.map((it,i)=>`
    <tr>
      <td style="text-align:center;">${i+1}</td>
      <td>${esc(it.label)}</td>
      <td style="text-align:right;">${it.amount ? fmtMoney(it.amount).replace('RM','').trim() : ''}</td>
      <td style="text-align:center;">✔</td>
    </tr>
  `).join('') + `<tr><td colspan="4">&nbsp;</td></tr>`.repeat(Math.max(0, 3 - items.length));

  const html = `
    <div class="pibg-receipt">
      <div class="pibg-rc-head">
        <img src="${PIBG_LOGO_SRC}" alt="" class="pibg-rc-logo">
        <div class="pibg-rc-title">
          <div class="pibg-rc-badge">Resit Rasmi</div>
          <div class="pibg-rc-org">${esc(SCHOOL_NAME_LINE1)}</div>
          <div class="pibg-rc-school">${esc(SCHOOL_NAME_LINE2)}</div>
        </div>
        <img src="${SCHOOL_BADGE_SRC}" alt="" class="pibg-rc-logo">
      </div>
      <div class="pibg-rc-no">No. <span class="mono">${esc(receiptNo)}</span></div>

      <div class="pibg-rc-field">Terima daripada : <span>${esc(PROFILE.displayName || PROFILE.email)}</span></div>
      <div class="pibg-rc-row">
        <div class="pibg-rc-field">Kelas : <span>${esc(CLASS.name)}</span></div>
        <div class="pibg-rc-field">Tarikh : <span>${esc(student.paidDate || todayStr())}</span></div>
      </div>

      <table class="pibg-rc-table">
        <thead><tr><th style="width:36px;">BIL</th><th>Untuk Bayaran</th><th style="width:70px;">RM</th><th style="width:70px;">Tandakan (✓)</th></tr></thead>
        <tbody>${rows}</tbody>
      </table>

      <div class="pibg-rc-words">Jumlah (Dengan Perkataan)<br>${esc(amountToWordsMY(total))}</div>

      <div class="pibg-rc-total">RM : <span class="mono">${fmtMoney(total).replace('RM','').trim()}</span></div>
      <div class="pibg-rc-sign">(Tandatangan Penerima)</div>
    </div>
  `;

  document.getElementById('printArea').innerHTML = html;
  document.body.classList.add('printing');
  setTimeout(()=>{
    window.print();
    document.body.classList.remove('printing');
  }, 50);
}

/* ---- Malay number-to-words, used for the receipt's "Jumlah (Dengan Perkataan)" line ---- */
function terbilangMY(num){
  num = Math.floor(num);
  if(num === 0) return 'kosong';
  const satuan = ['','satu','dua','tiga','empat','lima','enam','tujuh','lapan','sembilan','sepuluh','sebelas'];
  function convert(n){
    if(n < 12) return satuan[n];
    if(n < 20) return convert(n-10) + ' belas';
    if(n < 100){
      const puluh = Math.floor(n/10), baki = n%10;
      return convert(puluh) + ' puluh' + (baki ? ' ' + convert(baki) : '');
    }
    if(n < 200) return 'seratus' + (n-100 ? ' ' + convert(n-100) : '');
    if(n < 1000){
      const ratus = Math.floor(n/100), baki = n%100;
      return convert(ratus) + ' ratus' + (baki ? ' ' + convert(baki) : '');
    }
    if(n < 2000) return 'seribu' + (n-1000 ? ' ' + convert(n-1000) : '');
    if(n < 1000000){
      const ribu = Math.floor(n/1000), baki = n%1000;
      return convert(ribu) + ' ribu' + (baki ? ' ' + convert(baki) : '');
    }
    const juta = Math.floor(n/1000000), baki = n%1000000;
    return convert(juta) + ' juta' + (baki ? ' ' + convert(baki) : '');
  }
  return convert(num).replace(/\s+/g,' ').trim();
}

function amountToWordsMY(amount){
  const ringgit = Math.floor(amount);
  const sen = Math.round((amount - ringgit) * 100);
  let words = terbilangMY(ringgit);
  words = words.charAt(0).toUpperCase() + words.slice(1) + ' Ringgit Malaysia';
  if(sen > 0) words += ' ' + terbilangMY(sen) + ' Sen';
  return words + ' Sahaja';
}

function handleXlsxUpload(e){
  const file = e.target.files[0];
  if(!file || !CLASS) return;
  const reader = new FileReader();
  reader.onload = async (evt)=>{
    try{
      const data = new Uint8Array(evt.target.result);
      const wb = XLSX.read(data, {type:'array'});
      const sheet = wb.Sheets[wb.SheetNames[0]];
      const rows = XLSX.utils.sheet_to_json(sheet, {header:1});
      const existing = new Set(STUDENTS.map(s=>s.name.trim().toLowerCase()));
      const batch = db.batch();
      const col = studentsCollection();
      let added = 0;

      rows.forEach(row=>{
        if(!row || !row.length) return;
        const cells = row.map(c=>String(c||'').trim()).filter(Boolean);
        if(!cells.length) return;
        const withLetters = cells.filter(c=>/[a-zA-Z]/.test(c));
        const candidate = withLetters.length ? withLetters[withLetters.length-1] : cells[cells.length-1];
        if(!candidate) return;
        if(/^(name|nama|student|pelajar|no\.?|bil\.?)$/i.test(candidate)) return;
        const key = candidate.toLowerCase();
        if(existing.has(key)) return;
        existing.add(key);
        const ref = col.doc();
        batch.set(ref, {name:candidate, paid:false, paidDate:null, amount:null});
        STUDENTS.push({id:ref.id, name:candidate, paid:false, paidDate:null, amount:null});
        added++;
      });

      if(added){
        await batch.commit();
        STUDENTS.sort((a,b)=>a.name.localeCompare(b.name));
      }
      render();
      toast(added ? `Added ${added} student${added===1?'':'s'}.` : 'No new names found in that file.');
    }catch(err){
      console.error(err);
      toast('Could not read that file — please upload a valid .xlsx file.');
    }
    e.target.value = '';
  };
  reader.readAsArrayBuffer(file);
}